  const captions = new Map(Object.entries(placementNames).flatMap(([platform, placements]) =>
    placements.map(placement => [`${platform} ${placement}`, [platform, placement]])));
  const uppercaseCaptions = new Map([...captions.keys()].map(caption => [caption.toUpperCase(), caption]));
  const escapePattern = value => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const captionChoices = [...captions.keys()].map(escapePattern).join("|");
  const uppercaseCaptionChoices = [...uppercaseCaptions.keys()].map(escapePattern).join("|");
  const captionText = key => captions.get(key).map(translated).join(" ");
